contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        require(newOwner != address(0));

        address beforeOwner = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        assert(
            (reverted && afterOwner == beforeOwner) ||
            (!reverted && afterOwner == newOwner)
        );
    }

    receive() external payable {}
}

