contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        address ownerBefore = c.owner();
        bool callerIsOwner = (caller == ownerBefore);
        bool reverted;
        if (callerIsOwner) {
            c.transferOwnership(newOwner);
            reverted = false;
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
