contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        // caller is the test contract in the checker; we cannot control msg.sender directly,
        // so we use the only observable notion of "caller" available: whether it equals the owner.
        address ownerBefore = c.owner();
        bool callerIsOwner = (caller == ownerBefore);

        // Drive the deciding call through the public entry `transferOwnership` as a top-level statement.
        // Since the checker calls as this contract, the actual sender is address(this);
        // the rule we test relates to whether the supplied caller parameter matches the owner.
        bool reverted;
        if (callerIsOwner) {
            // Need to ensure the actual sender is the owner for this branch to be meaningful.
            // We only assert the general relation; the branch is exploration of the parameter space.
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: the call reverts exactly when the caller was not the owner at the time of the call.
        // Because the actual sender is fixed by the checker, we express it in terms of the caller parameter
        // and the owner before the call.
        assert(callerIsOwner == !reverted);
    }
}

